def portfolio(enabled=False):
    risk={'call':'returned_ok' if enabled else 'not_reached','skip':'none','reads':{}}
    if enabled:risk.update(manager_source='internal',lookback_period=21,reads={
        'var_limit':0.2,'jump_risk_limit':0.15,'max_correlation':0.9,'max_gross_leverage':2.0,
        'max_net_leverage':1.0,'confidence_level':0.95,'capital_exact':'1000'})
    return {'schema_version':'qt-equity-portfolio-consumption/v1','scope':'portfolio_invocation',
        'full_run_certification':False,'available':True,'unavailable_reason':None,'outcome':'returned_ok',
        'skip_execution_generation':False,'passes':[{'index':0,
            'reads':{'use_optimization':False,'use_risk_management':enabled},
            'optimization_helper':'not_reached','risk_helper':'returned_ok' if enabled else 'not_reached','risk':risk}],
        'strategy_charges':[{'index':0,'purpose':'per_strategy','strategy_id':'LIVE_EQUITY_MEAN_REVERSION','symbol':'SYN',
            'call':'returned_ok','reads':{'quantity':0.5,'reference_price':16.0,'input_source':'internally_tracked','asset_lookup_path':'exact_symbol'}}],
        'compatibility_charges':[{'index':0,'purpose':'compatibility','strategy_id':'','symbol':'SYN','call':'returned_ok',
            'reads':{'quantity':0.5,'reference_price':16.0,'input_source':'internally_tracked','asset_lookup_path':'exact_symbol'}}]}

def value(definition):
    if definition.get('ref')=='qt-equity-portfolio-consumption/v1':return portfolio()
    if 'const' in definition:return definition['const']
    if 'enum' in definition:return definition['enum'][0]
    kind=definition.get('type')
    if kind=='boolean':return False
    if kind=='integer':return 21
    if kind=='number':return 0.5
    if definition.get('format')=='date':return '2026-09-25'
    if definition.get('format')=='canonical-uuid':return '81000000-0000-4000-8000-000000000001'
    if definition.get('format')=='canonical-decimal8-checked-int64':return '0.14'
    if 'pattern' in definition:return 'a'*64
    if 'ref' in definition:return {'schema_version':'qt-equity-strategy-consumption/v1','available':True,
        'profile':'mean_reversion','scope':'strategy_invocation','full_run_certification':False,
        'symbols':{'SYN':{'reads':{'lookback_period':21,'entry_threshold':1.5},'observed_state':{}}}}
    return 'hold'

def sample():
    stages={}
    for name,definition in CONTRACT['stages'].items():
        reads={field:value(definition['reads'][field]) for field in definition['required']}
        if name in ('prior','corporate_actions','eod'):
            mode='system_reference' if name=='prior' else 'system_history' if name=='corporate_actions' else 'system_finalization'
            condition=CONTRACT['conditional_readsets'][name][mode]
            reads={field:value(definition['reads'][field]) for field in condition['required']}
        symbols={'SYN':{field:value(meta) for field,meta in definition['per_symbol_reads'].items()}} if 'per_symbol_reads' in definition else {}
        executions=[]
        if name=='execution':
            executions=[{'symbol':'SYN',**{k:KEY[k] for k in ('portfolio_id','strategy_id','strategy_name')},
                'index':0,'execution_id':'actual-fixture-ID','reads':{field:value(meta) for field,meta in definition['per_execution_reads'].items()}}]
        stages[name]={'outcome':'returned_ok','skip_reason':None,'reads':reads,'symbols':symbols,'executions':executions}
    stages['cost_history']['symbols']['SYN']['previous_close_forwarded']=0.0
    stages['cost_history']['symbols']['SYN'].pop('log_return_lookback_days')
    cost=stages['execution']['executions'][0]['reads']
    for field in ('explicit_fee_per_contract','max_commission_per_order','sec_fee_per_million',
        'finra_taf_per_share','finra_taf_cap_per_trade','volatility_lambda','volatility_min_multiplier','volatility_max_multiplier'):
        cost.pop(field)
    cost.update(retrieved_volatility_multiplier=1.0,effective_volatility_multiplier=1.0)
    return {'schema_version':CONTRACT['document_schema_version'],'catalog_version':CONTRACT['catalog_version'],
        'scope':'full_run','profile':'mean_reversion','run_key':deepcopy(KEY),'available':True,'complete':True,
        'unavailable_reason':None,'stages':stages}
